entries[25286] = { ["name"] = "Heldenhafter Stoß", ["text"] = "15 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 157 Punkt(e) erhöht und ein hohes Maß an Bedrohung erzeugt." }
entries[25288] = { ["name"] = "Rache", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Verteidigungshaltung\nFührt einen sofortigen Gegenangriff gegen den Feind aus, der 81 bis 99 Punkt(e) Schaden verursacht und dabei ein hohes Maß an Bedrohung generiert. 'Rache' muss auf Blocken, Ausweichen oder Parieren folgen." }
entries[25289] = { ["name"] = "Schlachtruf", ["text"] = "10 Wut\nSpontanzauber\nDer Krieger schreit, wodurch sich die Nahkampfangriffskraft der Gruppe innerhalb eines Radius von 20 Metern um 232 erhöht. Hält 2 Min. lang an." }
entries[25290] = { ["name"] = "Segen der Weisheit", ["text"] = "125 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und stellt 5 Min. lang alle 5 Sek. 33 Punkt(e) Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[25291] = { ["name"] = "Segen der Macht", ["text"] = "130 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und erhöht 5 Min. lang die Nahkampfangriffskraft um 185. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
