entries[25294] = { ["name"] = "Mehrfachschuss", ["text"] = "230 Mana 8 - 35 Meter Reichweite\nSofort 10 sek. Abklingzeit\nBenötigt Distanzwaffe\nFeuert mehrere Geschosse ab, trifft 3 Ziele und fügt zusätzliche 150 Punkt(e) Schaden zu." }
entries[25295] = { ["name"] = "Schlangenbiss", ["text"] = "250 Mana 8 - 35 Meter Reichweite\nBenötigt Distanzwaffe\nBeißt das Ziel und verursacht 15 Sek. lang 555 Naturschaden. Es kann immer nur ein Biss oder Stich pro Jäger auf einem einzelnen Ziel aktiv sein." }
entries[25296] = { ["name"] = "Aspekt des Falken", ["text"] = "120 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 120 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
