entries[25299] = { ["name"] = "Verjüngung", ["text"] = "360 Mana 40 Meter Reichweite\nSofort\nHeilt beim Ziel 12 Sek. lang 888 Punkt(e) Schaden." }
entries[25300] = { ["name"] = "Meucheln", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nDas Ziel meucheln und ihm 150% Waffenschaden plus 225 zufügen. Muss hinter dem Ziel sein. In der Waffenhand muss sich ein Dolch befinden. Gewährt 1 Combopunkt." }
entries[25302] = { ["name"] = "Finte", ["text"] = "20 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nEin Täuschungsmanöver wird durchgeführt, das zwar keinen Schaden verursacht, aber Eure Bedrohung um ein großes Maß verringert und die Wahrscheinlichkeit senkt, dass der Feind Euch angreift." }
entries[25304] = { ["name"] = "Frostblitz", ["text"] = "290 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Frostblitz auf den Gegner, der [Quellwert] bis [Quellwert] Frostschaden verursacht und 9 Sek. lang das Bewegungstempo um 40% verringert.", ["unresolvedValues"] = true }
