entries[25307] = { ["name"] = "Schattenblitz", ["text"] = "380 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Schattenblitz auf den Feind und verursacht 482 bis 538 Punkt(e) Schattenschaden." }
entries[25309] = { ["name"] = "Feuerbrand", ["text"] = "380 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Gegner und fügt ihm [Quellwert] Feuerschaden sowie im Verlauf von 15 Sek. insgesamt 510 zusätzlichen Feuerschaden zu.", ["unresolvedValues"] = true }
